@dataclass
class Account:
    path: str
    type: str
    currency: Optional[str] = None
    opened: Any = None
    closed: Any = None
    note: str = ""


@dataclass(frozen=True)
class Posting:
    account: str
    amount: Any = None
    note: str = ""


@dataclass
class Transaction:
    date: Any
    payee: str
    narration: str = ""
