        depth = path.count(":") + 1
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix) and a.path.count(":") == depth]

    def descendants(self, path):
        self.get(path)
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix)]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        acc = self.get(path)
        if acc.opened is not None and on < acc.opened:
            return False
        if acc.closed is not None and on > acc.closed:
            return False
        return True

    def close(self, path, on):
        acc = self.get(path)
        if not _is_date(on):
            raise ChartError("invalid closing date %r" % (on,))
        if acc.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if acc.opened is not None and on < acc.opened:
            raise ChartError("cannot close %s on %s, before it was opened on %s"
                             % (path, on.isoformat(), acc.opened.isoformat()))
        acc.closed = on
        return acc

    def matches(self, pattern):
        pat = _compile_pattern(pattern)
        return [a for a in self.accounts() if _matches(pat, a.path)]
"""Plain data records shared by the whole program."""

from dataclasses import dataclass, field
from typing import Any, List, Optional, Tuple


@dataclass
class Account:
    path: str
    type: str
    currency: Optional[str] = None
    opened: Any = None
    closed: Any = None
    note: str = ""


@dataclass(frozen=True)
class Posting:
    account: str
    amount: Any = None
    note: str = ""


@dataclass
class Transaction:
    date: Any
    payee: str
    narration: str = ""
    postings: List[Posting] = field(default_factory=list)
    tags: Tuple[str, ...] = ()
    flag: str = "*"
    id: Optional[int] = None
"""The ledger: validated transactions and balances."""

import datetime
import re

from tallybook.accounts import Chart
from tallybook.currency import RateTable
from tallybook.errors import NotFoundError, ValidationError, is_int
from tallybook.money import Money, format_minor
from tallybook.model import Posting, Transaction

__all__ = ["Ledger", "LedgerError"]

TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class LedgerError(ValidationError):
    """A transaction the ledger refuses."""


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _text_ok(value):
    return isinstance(value, str) and "\n" not in value and "\r" not in value


def clean_tags(tags):
    if isinstance(tags, (str, bytes)) or tags is None:
        raise LedgerError("tags must be a list of tag names, got %r" % (tags,))
    try:
        items = list(tags)
    except TypeError:
        raise LedgerError("tags must be a list of tag names, got %r" % (tags,)) from None
    for t in items:
        if not isinstance(t, str) or not TAG_RE.fullmatch(t):
            raise LedgerError("invalid tag %r" % (t,))
    return tuple(sorted(set(items)))


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # ------------------------------------------------------------------ checks
    def _prepare(self, tx, used_ids, max_id, keep_id=None):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not _is_date(tx.date):
            raise LedgerError("invalid transaction date %r" % (tx.date,))
        if tx.flag not in ("*", "!"):
            raise LedgerError("invalid flag %r: expected * or !" % (tx.flag,))
        if not _text_ok(tx.payee):
            raise LedgerError("invalid payee %r" % (tx.payee,))
        if not _text_ok(tx.narration):
            raise LedgerError("invalid narration %r" % (tx.narration,))
        tags = clean_tags(tx.tags)
        try:
            postings = list(tx.postings)
        except TypeError:
            raise LedgerError("postings must be a list") from None
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: %r" % (p,))
            if not _text_ok(p.note):
                raise LedgerError("invalid posting note %r" % (p.note,))
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("invalid posting amount %r" % (p.amount,))
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        datestr = tx.date.isoformat()
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % (p.account if isinstance(p.account, str)
                                                          else repr(p.account)))
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, datestr))
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            p = postings[i]
            new = [Posting(p.account, Money(-sums[c], c), p.note) for c in off]
            postings = postings[:i] + new + postings[i + 1:]
        elif off:
            raise LedgerError("transaction does not balance: %s"
                              % ", ".join("%s %s" % (c, format_minor(sums[c], c)) for c in off))
        for p in postings:
            acc = self.chart.get(p.account)
            if acc.currency is not None and p.amount.currency != acc.currency:
                raise LedgerError("account %s only holds %s, not %s" % (p.account, acc.currency, p.amount.currency))
        # id
        if keep_id is not None:
            if tx.id is not None and tx.id != keep_id:
                raise LedgerError("transaction id %r does not match %r" % (tx.id, keep_id))
            new_id = keep_id
        elif tx.id is None:
            new_id = max_id + 1
        else:
            if not is_int(tx.id) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in used_ids:
                raise LedgerError("transaction %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings, tags, tx.flag, new_id)

    # ---------------------------------------------------------------- changing
    def add(self, tx):
        stored = self._prepare(tx, self._txs, self._max_id)
        self._txs[stored.id] = stored
        self._max_id = max(self._max_id, stored.id)
        return stored

    def _load(self, tx):
        """Store an already-validated transaction (with its id) without checking it."""
        self._txs[tx.id] = tx
        self._max_id = max(self._max_id, tx.id)
        return tx

    def add_many(self, transactions):
        saved_txs = dict(self._txs)
        saved_max = self._max_id
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs = saved_txs
            self._max_id = saved_max
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %r" % (id,))
        stored = self._prepare(tx, self._txs, self._max_id, keep_id=id)
        self._txs[id] = stored
        return stored

    def get(self, id):
        try:
            return self._txs[id]
        except (KeyError, TypeError):
            raise NotFoundError("no transaction %r" % (id,)) from None

    def remove(self, id):
        tx = self.get(id)
        del self._txs[id]
        return tx

    # ----------------------------------------------------------------- reading
    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    def balances(self, as_of=None):
        out = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            d = out.setdefault(p.account, {})
            d[p.amount.currency] = d.get(p.amount.currency, 0) + p.amount.minor
        return _clean(out)

    def rollup_balances(self, as_of=None):
        out = {}
        for account, cur in self.balances(as_of).items():
            segs = account.split(":")
            for i in range(1, len(segs) + 1):
                d = out.setdefault(":".join(segs[:i]), {})
                for c, v in cur.items():
                    d[c] = d.get(c, 0) + v
        return _clean(out)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        self.chart.get(account)
        totals = {}
        prefix = account + ":"
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            if p.account == account or (rollup and p.account.startswith(prefix)):
                totals[p.amount.currency] = totals.get(p.amount.currency, 0) + p.amount.minor
        if currency is not None:
            return Money(totals.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(totals.items()) if v != 0}


def _clean(out):
    result = {}
    for account in sorted(out):
        cur = {c: v for c, v in sorted(out[account].items()) if v != 0}
        if cur:
            result[account] = cur
    return result

"""The journal file: a whole book as one readable text file."""

import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import account_type, valid_path
from tallybook.currency import CurrencyError, is_currency, parse_rate_text
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ParseError, TallybookError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, parse_amount

__all__ = ["Journal", "JournalError", "parse_journal", "format_journal", "format_transaction"]

_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_BLANKS = " \t"


class JournalError(ParseError):
    """A mistake in the writing of a journal file; `.line` is its 1-based line number."""

    def __init__(self, line, description="", **detail):
        if isinstance(line, str) and not description:
            # JournalError("line 3: ...") form, for completeness
            m = re.match(r"line ([0-9]+): ", line)
            message, line = line, (int(m.group(1)) if m else None)
        else:
            message = "line %d: %s" % (line, description)
        super().__init__(message, **detail)
        self.line = line


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: list = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def __post_init__(self):
        self.accounts = list(self.accounts)
        self.rates = list(self.rates)
        self.transactions = list(self.transactions)

    def to_ledger(self):
        ledger = Ledger()
        for acc in self.accounts:
            ledger.chart.add(acc.path, type=acc.type, currency=acc.currency, opened=acc.opened, note=acc.note)
            if acc.closed is not None:
                ledger.chart.close(acc.path, acc.closed)
        for src, dst, on, rate_text in self.rates:
            ledger.rates.set(src, dst, rate_text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# ---------------------------------------------------------------------- reading


class _Mistake(Exception):
    pass


def _tokenize(line):
    """Split a line into ("bare"|"quoted", text) items and the comment text after `;` (or None)."""
    items = []
    comment = None
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _BLANKS:
            i += 1
            continue
        if c == ";":
            comment = line[i + 1:]
            break
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _Mistake("missing closing quote")
                ch = line[j]
                if ch == "\\":
                    if j + 1 < n and line[j + 1] in '"\\':
                        buf.append(line[j + 1])
                        j += 2
                        continue
                    raise _Mistake("invalid backslash in quoted text")
                if ch == '"':
                    break
                buf.append(ch)
                j += 1
            j += 1
            if j < n and line[j] not in _BLANKS and line[j] != ";":
                raise _Mistake("unexpected text after closing quote")
            items.append(("quoted", "".join(buf)))
            i = j
            continue
        j = i
        while j < n and line[j] not in _BLANKS and line[j] != ";":
            j += 1
        items.append(("bare", line[i:j]))
        i = j
    return items, comment


def _date(text):
    try:
        return parse_date(text)
    except DateError:
        raise _Mistake("invalid date '%s'" % text) from None


def _bare(item, what):
    kind, text = item
    if kind != "bare":
        raise _Mistake("unexpected quoted text, expected %s" % what)
    return text


def _parse_account(items):
    # items[0] is "account"
    if len(items) < 2:
        raise _Mistake("missing account path")
    path = _bare(items[1], "an account path")
    if not valid_path(path):
        raise _Mistake("invalid account path '%s'" % path)
    rest = items[2:]
    cur = opened = closed = None
    note = ""
    k = 0
    if k < len(rest) and rest[k][0] == "bare" and rest[k][1] not in ("open", "close"):
        cur = rest[k][1]
        if not is_currency(cur):
            raise _Mistake("unknown currency '%s'" % cur)
        k += 1
    for word in ("open", "close"):
        if k < len(rest) and rest[k] == ("bare", word):
            if k + 1 >= len(rest):
                raise _Mistake("missing date after %s" % word)
            d = _date(_bare(rest[k + 1], "a date"))
            if word == "open":
                opened = d
            else:
                closed = d
            k += 2
    if k < len(rest) and rest[k][0] == "quoted":
        note = rest[k][1]
        k += 1
    if k < len(rest):
        raise _Mistake("unexpected '%s'" % rest[k][1])
    if opened is not None and closed is not None and closed < opened:
        raise _Mistake("account %s is closed before it is opened" % path)
    return Account(path, account_type(path), cur, opened, closed, note)


def _parse_rate(items):
    words = [_bare(it, "a rate part") for it in items[1:]]
    if len(words) != 4:
        raise _Mistake("expected 'rate DATE FROM TO RATE'")
    d = _date(words[0])
    src, dst, text = words[1], words[2], words[3]
    for code in (src, dst):
        if not is_currency(code):
            raise _Mistake("unknown currency '%s'" % code)
    if src == dst:
        raise _Mistake("a rate needs two different currencies")
    try:
        parse_rate_text(text)
    except CurrencyError:
        raise _Mistake("invalid rate '%s'" % text) from None
    return (src, dst, d, text)


def _parse_tx_line(items):
    d = _date(items[0][1])
    k = 1
    flag = "*"
    if k < len(items) and items[k][0] == "bare" and items[k][1] in ("*", "!"):
        flag = items[k][1]
        k += 1
    strings = []
    while k < len(items) and items[k][0] == "quoted":
        strings.append(items[k][1])
        k += 1
    if not strings:
        raise _Mistake("missing payee")
    if len(strings) > 2:
        raise _Mistake("too many quoted strings")
    tags = set()
    while k < len(items):
        kind, text = items[k]
        if kind != "bare" or not text.startswith("#") or not _TAG_RE.fullmatch(text[1:]):
            raise _Mistake("unexpected '%s'" % text)
        tags.add(text[1:])
        k += 1
    payee = strings[0]
    narration = strings[1] if len(strings) > 1 else ""
    return Transaction(d, payee, narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(items, comment):
    words = [_bare(it, "a posting part") for it in items]
    note = comment.strip(" \t") if comment is not None else ""
    if not words:
        raise _Mistake("missing account")
    path = words[0]
    if not valid_path(path):
        raise _Mistake("invalid account path '%s'" % path)
    if len(words) == 1:
        return Posting(path, None, note)
    if len(words) == 2:
        raise _Mistake("missing currency after amount")
    if len(words) > 3:
        raise _Mistake("unexpected '%s'" % words[3])
    amount, code = words[1], words[2]
    if not is_currency(code):
        raise _Mistake("unknown currency '%s'" % code)
    try:
        minor = parse_amount(amount, code)
    except TallybookError as e:
        raise _Mistake(e.message) from None
    return Posting(path, Money(minor, code), note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "expected text, got %r" % (text,))
    if text.startswith("﻿"):
        text = text[1:]
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    journal = Journal()
    declared = set()
    current = None  # the Transaction whose postings are being read
    for number, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        try:
            stripped = line.lstrip(_BLANKS)
            if not stripped:
                current = None
                continue
            if stripped[0] in ";#":
                continue
            items, comment = _tokenize(line)
            if line[0] in _BLANKS:
                if current is None:
                    raise _Mistake("indented line outside a transaction")
                current.postings.append(_parse_posting(items, comment))
                continue
            current = None
            head = items[0] if items else ("bare", "")
            if head == ("bare", "account"):
                acc = _parse_account(items)
                if acc.path in declared:
                    raise _Mistake("account %s is declared twice" % acc.path)
                declared.add(acc.path)
                journal.accounts.append(acc)
            elif head == ("bare", "rate"):
                journal.rates.append(_parse_rate(items))
            elif head[0] == "bare" and head[1][:1].isdigit():
                current = _parse_tx_line(items)
                journal.transactions.append(current)
            else:
                raise _Mistake("unexpected '%s'" % head[1])
        except _Mistake as e:
            raise JournalError(number, str(e)) from None
    return journal


# ---------------------------------------------------------------------- writing


def _quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _account_line(acc):
    parts = ["account", acc.path]
    if acc.currency is not None:
        parts.append(acc.currency)
    if acc.opened is not None:
        parts += ["open", format_date(acc.opened)]
    if acc.closed is not None:
        parts += ["close", format_date(acc.closed)]
    if acc.note:
        parts.append(_quote(acc.note))
    return " ".join(parts)


def _rate_line(rate):
    src, dst, on, text = rate
    return "rate %s %s %s %s" % (format_date(on), src, dst, text)


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for tag in sorted(set(tx.tags)):
        head += " #" + tag
    lines = [head]
    with_amount = [p for p in tx.postings if p.amount is not None]
    acc_width = max((len(p.account) for p in with_amount), default=0)
    amt_width = max((len(p.amount.amount_str()) for p in with_amount), default=0)
    for p in tx.postings:
        if p.amount is None:
            line = "  " + p.account
        else:
            line = "  %s  %s %s" % (p.account.ljust(acc_width), p.amount.amount_str().rjust(amt_width),
                                    p.amount.currency)
        if p.note:
            line += "  ; " + p.note
        lines.append(line)
    return "\n".join(lines) + "\n"


def format_journal(journal):
    groups = []
    if journal.accounts:
        groups.append("".join(_account_line(a) + "\n" for a in journal.accounts))
    if journal.rates:
        groups.append("".join(_rate_line(r) + "\n" for r in journal.rates))
    if journal.transactions:
        groups.append("\n".join(format_transaction(t) for t in journal.transactions))
    return "\n".join(groups)

"""The query language for finding transactions."""

import operator
import re
from fractions import Fraction

from tallybook.currency import is_currency
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_query", "select", "Query", "QueryError"]


class QueryError(ParseError):
    """A query that cannot be understood; `.position` is the 1-based place of the mistake."""

    def __init__(self, description, position, **detail):
        super().__init__("%s at position %d" % (description, position), **detail)
        self.position = position


_SPACES = " \t"
_STOP = " \t()"
_NAME_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]*")
_OP_RE = re.compile(r"<=|>=|!=|<|>|=")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_COMPARABLE = ("date", "amount")
_KEYWORDS = ("and", "or", "not")
_OPS = {
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
    "=": operator.eq,
    "!=": operator.ne,
}


# ------------------------------------------------------------------ the tree


class _Node:
    on_posting = False

    def eval(self, tx, posting):  # pragma: no cover - overridden
        raise NotImplementedError


class _And(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) and self.right.eval(tx, posting)


class _Or(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) or self.right.eval(tx, posting)


class _Not(_Node):
    def __init__(self, inner):
        self.inner = inner

    def eval(self, tx, posting):
        return not self.inner.eval(tx, posting)


class _Contains(_Node):
    def __init__(self, fields, text):
        self.fields = fields
        self.text = text.lower()

    def eval(self, tx, posting):
        for f in self.fields:
            value = getattr(tx, f, None)
            if isinstance(value, str) and self.text in value.lower():
                return True
        return False


class _Tag(_Node):
    def __init__(self, name):
        self.name = name.lower()

    def eval(self, tx, posting):
        return any(isinstance(t, str) and t.lower() == self.name for t in (tx.tags or ()))


class _InPeriod(_Node):
    def __init__(self, period):
        self.period = period

    def eval(self, tx, posting):
        return self.period.start <= tx.date <= self.period.end


class _DateCmp(_Node):
    def __init__(self, op, date):
        self.op, self.date = _OPS[op], date

    def eval(self, tx, posting):
        return self.op(tx.date, self.date)


class _Flag(_Node):
    def __init__(self, flag):
        self.flag = flag

    def eval(self, tx, posting):
        return tx.flag == self.flag


class _Id(_Node):
    def __init__(self, value):
        self.value = value

    def eval(self, tx, posting):
        return tx.id is not None and not isinstance(tx.id, bool) and tx.id == self.value


class _Account(_Node):
    def __init__(self, parts):
        self.parts = parts

    def eval(self, tx, posting):
        return isinstance(posting.account, str) and _pattern_matches(self.parts, posting.account)


class _AmountCmp(_Node):
    def __init__(self, op, value, code):
        self.op, self.value, self.code = _OPS[op], value, code

    def eval(self, tx, posting):
        m = posting.amount
        if m is None:
            return False
        if self.code is not None and m.currency != self.code:
            return False
        return self.op(Fraction(m.minor, 10 ** m.exponent), self.value)


