class RulesError(ParseError):
    """A mistake in a rules file; .line is the 1-based line of the first bad rule."""

    def __init__(self, message="", line=None, **detail):
        super().__init__(message, **detail)
        self.line = line


class _Bad(Exception):
    """Internal: a problem on the line being parsed."""


_LINE_SPLIT_RE = re.compile(r"\r\n|\n|\r")
_OP_CHARS = "<>=!~"
_OPS = ("<=", ">=", "!=", "!~", "<", ">", "=", "~")
_SPACE = " \t"
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")

_TEXT_FIELDS = ("payee", "narration")
_ORDER_FIELDS = ("amount", "date")
_TEXT_OPS = ("=", "!=", "~", "!~")
_ORDER_OPS = ("<", "<=", ">", ">=", "=", "!=")
_ACTIONS = ("account", "tag", "narration", "payee", "flag")

# token kinds
_WORD, _STR, _OP = "word", "string", "operator"


def _tokenize(line):
    tokens = []
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _SPACE:
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _Bad("string is never closed")
                ch = line[j]
                if ch == "\\":
                    if j + 1 >= n:
                        raise _Bad("string is never closed")
                    nxt = line[j + 1]
                    if nxt == '"':
                        buf.append('"')
                    else:
                        buf.append(ch + nxt)
                    j += 2
                    continue
                if ch == '"':
                    break
                buf.append(ch)
                j += 1
            tokens.append((_STR, "".join(buf)))
            i = j + 1
            continue
        if c in _OP_CHARS:
            two = line[i:i + 2]
            if two in _OPS:
                tokens.append((_OP, two))
                i += 2
                continue
            if c == "!":
                # a lone "!" is a word (as in "flag !")
                tokens.append((_WORD, "!"))
                i += 1
                continue
            tokens.append((_OP, c))
            i += 1
            continue
        j = i
        while j < n and line[j] not in _SPACE and line[j] != '"' and line[j] not in _OP_CHARS:
            j += 1
        tokens.append((_WORD, line[i:j]))
        i = j
    return tokens


def _show(tok):
    if tok is None:
        return "end of line"
    kind, text = tok
    if kind == _STR:
        return '"%s"' % text
    return "'%s'" % text


class _Cond:
    __slots__ = ("field", "op", "value", "code", "regex")

    def __init__(self, field, op, value, code=None, regex=None):
        self.field = field
        self.op = op
        self.value = value
        self.code = code
        self.regex = regex

    def holds(self, fields):
        f = self.field
        if f in _TEXT_FIELDS:
            text = fields.get(f)
            if text is None:
                text = ""
            text = str(text)
            if self.op == "=":
                return text.casefold() == self.value.casefold()
            if self.op == "!=":
                return text.casefold() != self.value.casefold()
            found = self.regex.search(text) is not None
            return found if self.op == "~" else not found
        if f == "amount":
            money = fields.get("amount")
            if money is None:
                return False
            if self.code is not None and money.currency != self.code:
                return False
            left = Fraction(money.minor, 10 ** currency(money.currency).exponent)
        else:
            left = fields.get("date")
            if not isinstance(left, datetime.date):
                return False
            if isinstance(left, datetime.datetime):
                left = left.date()
        right = self.value
        op = self.op
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
        if op == "=":
            return left == right
        return left != right


class Rule:
    """One rule: conditions (empty for `any`) and actions."""

    def __init__(self, line, conditions, account=None, tags=(), narration=None, payee=None, flag=None,
                 text=""):
        self.line = line
        self.conditions = tuple(conditions)
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag
        self.text = text

    def matches(self, fields):
        return all(c.holds(fields) for c in self.conditions)

    def actions(self):
        out = {}
        if self.account is not None:
            out["account"] = self.account
        if self.tags:
            out["tags"] = list(self.tags)
        if self.narration is not None:
            out["narration"] = self.narration
        if self.payee is not None:
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out

    def __repr__(self):
        return "Rule(line=%d, %r)" % (self.line, self.text)


def _parse_condition(tokens, pos):
    """Parse one condition starting at tokens[pos]; returns (cond, new_pos)."""
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or tok[0] != _WORD:
        raise _Bad("expected a condition, found %s" % _show(tok))
    field = tok[1]
    if field in ("then", "and"):
        raise _Bad("expected a condition, found %s" % _show(tok))
    if field not in _TEXT_FIELDS and field not in _ORDER_FIELDS:
        raise _Bad("unknown field %s" % _show(tok))
    pos += 1
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or tok[0] != _OP:
        raise _Bad("expected an operator after '%s', found %s" % (field, _show(tok)))
    op = tok[1]
    allowed = _TEXT_OPS if field in _TEXT_FIELDS else _ORDER_OPS
    if op not in allowed:
        raise _Bad("operator '%s' does not work with '%s'" % (op, field))
    pos += 1
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or (tok[0] == _WORD and tok[1] in ("then", "and")):
        raise _Bad("missing value after '%s %s'" % (field, op))
    if field in _TEXT_FIELDS:
        if tok[0] != _STR:
            raise _Bad("expected a quoted text after '%s %s', found %s" % (field, op, _show(tok)))
        value = tok[1]
        regex = None
        if op in ("~", "!~"):
            try:
                regex = re.compile(value, re.IGNORECASE)
            except (re.error, OverflowError, RecursionError, ValueError) as e:
                raise _Bad('invalid regular expression "%s": %s' % (value, e))
        return _Cond(field, op, value, regex=regex), pos + 1
    if tok[0] != _WORD:
        raise _Bad("expected a %s after '%s %s', found %s" % (
            "number" if field == "amount" else "date", field, op, _show(tok)))
    text = tok[1]
    if field == "amount":
        m = _AMOUNT_RE.fullmatch(text)
        if not m:
            raise _Bad("invalid amount '%s'" % text)
        number, code = m.groups()
        if code:
            if not re.fullmatch(r"[A-Z]{3}", code):
                raise _Bad("invalid amount '%s': the currency code must be three upper-case letters" % text)
            if not is_currency(code):
                raise _Bad("invalid amount '%s': unknown currency %s" % (text, code))
        return _Cond(field, op, Fraction(number), code=code or None), pos + 1
    try:
        value = parse_date(text)
    except DateError:
        raise _Bad("invalid date '%s': expected a real YYYY-MM-DD date" % text)
    return _Cond(field, op, value), pos + 1


def _parse_line(text, lineno):
    tokens = _tokenize(text)
    if not tokens or tokens[0] != (_WORD, "when"):
        raise _Bad("a rule starts with 'when'")
    pos = 1
    conditions = []
    if pos < len(tokens) and tokens[pos] == (_WORD, "any"):
        pos += 1
        tok = tokens[pos] if pos < len(tokens) else None
        if tok != (_WORD, "then"):
            if tok == (_WORD, "and"):
                raise _Bad("'any' cannot be combined with other conditions")
            if tok is None:
                raise _Bad("missing 'then'")
            raise _Bad("expected 'then' after 'any', found %s" % _show(tok))
    else:
        while True:
            cond, pos = _parse_condition(tokens, pos)
            conditions.append(cond)
            tok = tokens[pos] if pos < len(tokens) else None
            if tok == (_WORD, "and"):
                pos += 1
                if pos < len(tokens) and tokens[pos] == (_WORD, "any"):
                    raise _Bad("'any' cannot be combined with other conditions")
                continue
            if tok == (_WORD, "then"):
                break
            if tok is None:
                raise _Bad("missing 'then'")
            raise _Bad("expected 'and' or 'then', found %s" % _show(tok))
    pos += 1  # past "then"
    if pos >= len(tokens):
        raise _Bad("nothing after 'then'")
    account = narration = payee = flag = None
    tags = []
    seen = set()
    while pos < len(tokens):
        tok = tokens[pos]
        if tok[0] != _WORD or tok[1] not in _ACTIONS:
            if tok[0] == _WORD and tok[1].isalpha() and tok[1].islower():
                raise _Bad("unknown action %s" % _show(tok))
            raise _Bad("expected an action, found %s" % _show(tok))
        name = tok[1]
        if name != "tag":
            if name in seen:
                raise _Bad("'%s' given twice" % name)
            seen.add(name)
        pos += 1
        val = tokens[pos] if pos < len(tokens) else None
        if val is None:
            raise _Bad("missing value after '%s'" % name)
        pos += 1
        if name in ("narration", "payee"):
            if val[0] != _STR:
                raise _Bad("expected a quoted text after '%s', found %s" % (name, _show(val)))
            if name == "narration":
                narration = val[1]
            else:
                if not val[1].strip():
                    raise _Bad("the payee cannot be empty")
                payee = val[1]
            continue
        if val[0] != _WORD:
            raise _Bad("expected a value after '%s', found %s" % (name, _show(val)))
        word = val[1]
        if name == "account":
            if not valid_any_root_path(word):
                raise _Bad("invalid account path '%s'" % word)
            account = word
        elif name == "tag":
            if not _TAG_RE.fullmatch(word):
                raise _Bad("invalid tag name '%s'" % word)
            low = word.lower()
            if low not in tags:
                tags.append(low)
        else:
            if word not in ("*", "!"):
                raise _Bad("invalid flag '%s': expected * or !" % word)
            flag = word
    return Rule(lineno, conditions, account=account, tags=tags, narration=narration, payee=payee,
                flag=flag, text=text.strip())


def parse_rules(text):
    """Read a rules file into a RuleSet (RulesError on the first bad rule)."""
    if not isinstance(text, str):
        raise RulesError("rules must be text, got %r" % (text,), line=None)
    if text.startswith("﻿"):
        text = text[1:]
    rules = []
    if text == "":
        return RuleSet(rules)
    for lineno, line in enumerate(_LINE_SPLIT_RE.split(text), 1):
        stripped = line.strip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        try:
            rules.append(_parse_line(line, lineno))
        except _Bad as e:
            raise RulesError("line %d: %s" % (lineno, e), line=lineno) from None
    return RuleSet(rules)


class RuleSet:
    """Rules in file order; the first one whose conditions all hold wins."""

    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(list(self._rules))

    def __repr__(self):
        return "RuleSet(%d rules)" % len(self._rules)

    def match(self, fields):
        for rule in self._rules:
            if rule.matches(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        if rule is None:
            return None
        return rule.actions()

    def categorize(self, tx):
        postings = list(tx.postings or [])
        fields = {
            "payee": tx.payee,
            "narration": tx.narration,
            "date": tx.date,
            "amount": postings[0].amount if postings else None,
        }
        rule = self.match(fields)
        if rule is None:
            return tx
        changes = {"tags": tuple(sorted(set(tx.tags or ()) | set(rule.tags)))}
        if rule.payee is not None:
            changes["payee"] = rule.payee
        if rule.narration is not None:
            changes["narration"] = rule.narration
        if rule.flag is not None:
            changes["flag"] = rule.flag
        if rule.account is not None and len(postings) == 2:
            postings[1] = dataclasses.replace(postings[1], account=rule.account)
        changes["postings"] = postings
        return dataclasses.replace(tx, **changes)

"""Importing bank statements (CSV) through a profile."""

import datetime
import re
from collections import Counter

from tallybook.accounts import valid_any_root_path
from tallybook.currency import currency, is_currency
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.rules import RuleSet, parse_rules

__all__ = ["parse_profile", "ImportProfile", "import_csv", "ImportResult", "CsvImportError"]


class CsvImportError(ParseError):
    """A bad profile, or a file that cannot be imported at all."""

    def __init__(self, message="", line=None, **detail):
        super().__init__(message, **detail)
        self.line = line


class _Bad(Exception):
    pass


_LINE_SPLIT_RE = re.compile(r"\r\n|\n|\r")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")
_COLUMN_SETTINGS = ("date_column", "payee_column", "narration_column", "amount_column", "debit_column",
                    "credit_column")
_SETTINGS = _COLUMN_SETTINGS + ("currency", "account", "default_account", "date_format", "delimiter", "skip_rows",
                                "has_header", "negate", "decimal_separator", "thousands_separator", "flag", "tags")
_REQUIRED = ("date_column", "payee_column", "currency", "account")
_BOOLS = {"yes": True, "true": True, "no": False, "false": False}
_DELIMITER_WORDS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'",
              ",": ",", ".": ".", "'": "'", " ": " "}

_MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
           "november", "december"]
_MONTH_FULL = {name: i for i, name in enumerate(_MONTHS, 1)}
_MONTH_ABBR = {name[:3]: i for i, name in enumerate(_MONTHS, 1)}


class ImportProfile:
    """How one bank lays out its CSV statements."""

    def __init__(self, date_column=None, payee_column=None, narration_column=None, amount_column=None,
                 debit_column=None, credit_column=None, currency=None, account=None, default_account=None,
                 date_format="%Y-%m-%d", delimiter=",", skip_rows=0, has_header=True, negate=False,
                 decimal_separator=".", thousands_separator="", flag="*", tags=()):
        self.date_column = date_column
        self.payee_column = payee_column
        self.narration_column = narration_column
        self.amount_column = amount_column
        self.debit_column = debit_column
        self.credit_column = credit_column
        self.currency = currency
        self.account = account
        self.default_account = default_account
        self.date_format = date_format
        self.delimiter = delimiter
        self.skip_rows = skip_rows
        self.has_header = has_header
        self.negate = negate
        self.decimal_separator = decimal_separator
        self.thousands_separator = thousands_separator
        self.flag = flag
        self.tags = tuple(tags)

    def _items(self):
        return tuple((name, getattr(self, name)) for name in _SETTINGS)

    def __eq__(self, other):
        return isinstance(other, ImportProfile) and self._items() == other._items()

    def __ne__(self, other):
        return not self.__eq__(other)

    def __repr__(self):
        return "ImportProfile(%s)" % ", ".join("%s=%r" % kv for kv in self._items())


# ---------------------------------------------------------------- date formats

def _compile_date_format(fmt):
    """A regex and a list of group kinds for a date format; _Bad when the format is wrong."""
    parts = []
    kinds = []
    i, n = 0, len(fmt)
    while i < n:
        c = fmt[i]
        if c != "%":
            parts.append(re.escape(c))
            i += 1
            continue
        if i + 1 >= n:
            raise _Bad("invalid date_format '%s': a lone %% at the end" % fmt)
        d = fmt[i + 1]
        i += 2
        if d == "%":
            parts.append("%")
        elif d == "Y":
            parts.append("([0-9]{4})")
            kinds.append("Y")
        elif d == "y":
            parts.append("([0-9]{2})")
            kinds.append("y")
        elif d == "m":
            parts.append("([0-9]{1,2})")
            kinds.append("m")
        elif d == "d":
            parts.append("([0-9]{1,2})")
            kinds.append("d")
        elif d == "b":
            parts.append("([A-Za-z]{3})")
            kinds.append("b")
        elif d == "B":
            parts.append("([A-Za-z]+)")
            kinds.append("B")
        else:
            raise _Bad("invalid date_format '%s': unknown directive %%%s" % (fmt, d))
    years = sum(k in "Yy" for k in kinds)
    months = sum(k in "mbB" for k in kinds)
    days = sum(k == "d" for k in kinds)
    if years != 1 or months != 1 or days != 1:
        raise _Bad("invalid date_format '%s': needs a year, a month and a day, each once" % fmt)
    return re.compile("".join(parts)), kinds


def _parse_date_cell(text, fmt, compiled):
    regex, kinds = compiled
    m = regex.fullmatch(text)
    if m:
        year = month = day = None
        for kind, value in zip(kinds, m.groups()):
            if kind == "Y":
                year = int(value)
            elif kind == "y":
                year = 2000 + int(value)
            elif kind == "m":
                month = int(value)
            elif kind == "d":
                day = int(value)
            elif kind == "b":
                month = _MONTH_ABBR.get(value.lower())
            else:
                month = _MONTH_FULL.get(value.lower())
        if month is not None:
            try:
                return datetime.date(year, month, day)
            except ValueError:
                pass
    raise _Bad("invalid date '%s': expected a real date written %s" % (text, fmt))


# ---------------------------------------------------------------- profile

def _check_column(value, has_header):
    if value == "":
        raise _Bad("empty column")
    if value.startswith("#"):
        digits = value[1:]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise _Bad("invalid column '%s': expected #N, a column number from 1" % value)
        if int(digits) == 0:
            raise _Bad("invalid column '%s': columns are counted from 1" % value)
        return value
    if not has_header:
        raise _Bad("invalid column '%s': with has_header = no only #N columns are allowed" % value)
    return value


def _strip_value(raw):
    value = raw.strip(" ")
    if value != "\t":
        value = value.strip(" \t")
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        value = value[1:-1]
    return value


def parse_profile(text):
    """Read a profile text into an ImportProfile (CsvImportError when it is bad)."""
    if not isinstance(text, str):
        raise CsvImportError("a profile must be text, got %r" % (text,))
    if text.startswith("﻿"):
        text = text[1:]
    lines = []
    for lineno, line in enumerate(_LINE_SPLIT_RE.split(text), 1):
        stripped = line.strip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        lines.append((lineno, line))

    # has_header may come after the columns: look it up first (a bad value is reported on its own line).
    has_header = True
    for lineno, line in lines:
        if "=" in line:
            name, raw = line.split("=", 1)
            if name.strip(" \t") == "has_header":
                v = _BOOLS.get(_strip_value(raw).lower())
                if v is not None:
                    has_header = v
                break

    values = {}
    for lineno, line in lines:
        try:
            if "=" not in line:
                raise _Bad("expected 'setting = value'")
            name, raw = line.split("=", 1)
            name = name.strip(" \t")
            value = _strip_value(raw)
            if name not in _SETTINGS:
                raise _Bad("unknown setting '%s'" % name)
            if name in values:
                raise _Bad("setting '%s' given twice" % name)
            values[name] = _check_setting(name, value, has_header)
        except _Bad as e:
            raise CsvImportError("line %d: %s" % (lineno, e), line=lineno) from None

    for name in _REQUIRED:
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        raise CsvImportError("amount_column cannot be used together with debit_column/credit_column")
    if not has_amount:
        if has_debit != has_credit:
            raise CsvImportError("debit_column and credit_column must be given together")
        if not has_debit:
            raise CsvImportError("missing amount_column (or debit_column and credit_column)")
    profile = ImportProfile(**values)
    if profile.decimal_separator == profile.thousands_separator:
        raise CsvImportError("decimal_separator and thousands_separator cannot be the same")
    return profile


def _check_setting(name, value, has_header):
    if name in _COLUMN_SETTINGS:
        return _check_column(value, has_header)
    if name in ("account", "default_account"):
        if not valid_any_root_path(value):
            raise _Bad("invalid account path '%s'" % value)
        return value
    if name == "currency":
        if not is_currency(value):
            raise _Bad("unknown currency '%s'" % value)
        return value
    if name == "date_format":
        _compile_date_format(value)
        return value
    if name == "delimiter":
        if value in _DELIMITER_WORDS:
            return _DELIMITER_WORDS[value]
        if len(value) != 1 or value in '"\r\n':
            raise _Bad("invalid delimiter '%s'" % value)
        return value
    if name == "skip_rows":
        if not value or not value.isascii() or not value.isdigit():
            raise _Bad("invalid skip_rows '%s': expected a whole number" % value)
        return int(value)
    if name in ("has_header", "negate"):
        v = _BOOLS.get(value.lower())
        if v is None:
            raise _Bad("invalid %s '%s': expected yes, no, true or false" % (name, value))
        return v
    if name == "decimal_separator":
        if value not in (".", ","):
            raise _Bad("invalid decimal_separator '%s': expected . or ," % value)
        return value
    if name == "thousands_separator":
        if value not in _THOUSANDS:
            raise _Bad("invalid thousands_separator '%s'" % value)
        return _THOUSANDS[value]
    if name == "flag":
        if value not in ("*", "!"):
            raise _Bad("invalid flag '%s': expected * or !" % value)
        return value
    # tags
    if not value.strip():
        raise _Bad("tags cannot be empty")
    tags = set()
    for part in value.split(","):
        part = part.strip(" \t")
        if not _TAG_RE.fullmatch(part):
            raise _Bad("invalid tag name '%s'" % part)
        tags.add(part.lower())
    return tuple(sorted(tags))


# ---------------------------------------------------------------- reading CSV

def _skip_lines(text, count):
    """Drop `count` lines (any line ending); returns (rest, number of lines dropped)."""
    pos = 0
    dropped = 0
    n = len(text)
    while dropped < count and pos < n:
        m = _LINE_SPLIT_RE.search(text, pos)
        if m is None:
            pos = n
        else:
            pos = m.end()
        dropped += 1
    return text[pos:], dropped


def _read_records(text, delimiter, first_line):
    """Yield (line_number, cells) for every CSV record."""
    records = []
    i, n = 0, len(text)
    line = first_line
    while i < n:
        start = line
        cells = []
        cell = []
        while True:
            # read one field
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            cell.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    cell.append(c)
                    i += 1
            # unquoted part (or what follows a closing quote)
            while i < n and text[i] != delimiter and text[i] != "\n" and not text.startswith("\r\n", i):
                cell.append(text[i])
                i += 1
            cells.append("".join(cell))
            cell = []
            if i >= n:
                break
            if text[i] == delimiter:
                i += 1
                if i >= n:
                    cells.append("")
                    break
                continue
            # line end
            i += 2 if text[i] == "\r" else 1
            line += 1
            break
        records.append((start, cells))
    return records


# ---------------------------------------------------------------- amounts

def _amount_regex(decimal, thousands):
    d = re.escape(decimal)
    if thousands:
        t = re.escape(thousands)
        whole = r"(?:[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+)" % t
    else:
        whole = r"[0-9]+"
    return re.compile(r"(%s)(?:%s([0-9]+))?" % (whole, d))


def _parse_amount_cell(text, profile, regex, exponent):
    """Signed minor units for a cell (already trimmed); _Bad when it is not an amount."""
    if text == "":
        raise _Bad("empty amount")
    body = text
    negative = False
    if len(body) >= 2 and body[0] == "(" and body[-1] == ")":
        body = body[1:-1]
        negative = True
        sign_ok = False
    else:
        sign_ok = True
    if sign_ok and body[:1] in ("+", "-"):
        negative = body[0] == "-"
        body = body[1:]
    m = regex.fullmatch(body)
    if not m:
        raise _Bad("invalid amount '%s'" % text)
    whole, frac = m.groups()
    if profile.thousands_separator:
        whole = whole.replace(profile.thousands_separator, "")
    frac = frac or ""
    if len(frac) > exponent:
        raise _Bad("invalid amount '%s': %s has %s" % (
            text, profile.currency, "no decimals" if exponent == 0 else "at most %d decimals" % exponent))
    value = int(whole) * 10 ** exponent + (int(frac.ljust(exponent, "0")) if exponent else 0)
    return -value if negative else value


# ---------------------------------------------------------------- import

class ImportResult:
    """What an import produced: new transactions, duplicates and bad rows."""

    def __init__(self, transactions=None, duplicates=None, errors=None):
        self.transactions = list(transactions or [])
        self.duplicates = list(duplicates or [])
        self.errors = list(errors or [])

    def __repr__(self):
        return "ImportResult(%d transactions, %d duplicates, %d errors)" % (
            len(self.transactions), len(self.duplicates), len(self.errors))


def _clean(text):
    return " ".join(text.split())


def _key(tx, account):
    for p in tx.postings or ():
        if p.account == account:
            return (tx.date, p.amount, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    """Turn a CSV statement into transactions (see ImportResult)."""
    if isinstance(profile, str):
        profile = parse_profile(profile)
    if not isinstance(profile, ImportProfile):
        raise CsvImportError("profile must be an ImportProfile or profile text, got %r" % (profile,))
    if isinstance(rules, str):
        rules = parse_rules(rules)
    if rules is not None and not isinstance(rules, RuleSet):
        raise CsvImportError("rules must be a RuleSet, rules text or None, got %r" % (rules,))
    if not isinstance(text, str):
        raise CsvImportError("the CSV file must be text, got %r" % (text,))
    if text.startswith("﻿"):
        text = text[1:]

    rest, dropped = _skip_lines(text, profile.skip_rows)
    records = _read_records(rest, profile.delimiter, dropped + 1)
    records = [(ln, cells) for ln, cells in records if any(c.strip() for c in cells)]

    # resolve columns to 0-based indexes
    columns = {}
    names = [n for n in _COLUMN_SETTINGS if getattr(profile, n) is not None]
    if profile.has_header:
        if not records:
            raise CsvImportError("the file has no header")
        header = [c.strip().casefold() for c in records[0][1]]
        records = records[1:]
    for name in names:
        spec = getattr(profile, name)
        if spec.startswith("#") and spec[1:].isdigit():
            columns[name] = int(spec[1:]) - 1
            continue
        if not profile.has_header:
            raise CsvImportError("column '%s' needs a header: use #N with has_header = no" % spec)
        want = spec.strip().casefold()
        if want not in header:
            raise CsvImportError("column '%s' is not in the header" % spec)
        columns[name] = header.index(want)

    fmt = profile.date_format
    compiled = _compile_date_format(fmt)
    exponent = currency(profile.currency).exponent
    amount_re = _amount_regex(profile.decimal_separator, profile.thousands_separator)

    built = []  # (row, tx)
    errors = []
    for row, cells in records:
        try:
            def cell(name):
                idx = columns[name]
                if idx >= len(cells):
                    raise _Bad("row has no column '%s'" % getattr(profile, name))
                return cells[idx]

            date_text = cell("date_column").strip()
            payee_text = cell("payee_column")
            if profile.amount_column is not None:
                amount_cells = [cell("amount_column")]
            else:
                amount_cells = [cell("debit_column"), cell("credit_column")]
            narration = ""
            if "narration_column" in columns and columns["narration_column"] < len(cells):
                narration = _clean(cells[columns["narration_column"]])

            on = _parse_date_cell(date_text, fmt, compiled)
            payee = _clean(payee_text)
            if not payee:
                raise _Bad("empty payee")
            if profile.amount_column is not None:
                minor = _parse_amount_cell(amount_cells[0].strip(), profile, amount_re, exponent)
            else:
                debit, credit = (c.strip() for c in amount_cells)
                if debit and credit:
                    raise _Bad("both debit '%s' and credit '%s' are filled" % (debit, credit))
                if not debit and not credit:
                    raise _Bad("neither debit nor credit is filled")
                if credit:
                    minor = _parse_amount_cell(credit, profile, amount_re, exponent)
                else:
                    minor = -_parse_amount_cell(debit, profile, amount_re, exponent)
            if profile.negate:
                minor = -minor
            if minor == 0:
                raise _Bad("amount is zero")
            amount = Money(minor, profile.currency)

            counter = None
            flag = profile.flag
            tags = set(profile.tags)
            if rules is not None:
                rule = rules.match({"payee": payee, "narration": narration, "date": on, "amount": amount})
                if rule is not None:
                    counter = rule.account
                    if rule.payee is not None:
                        payee = rule.payee
                    if rule.narration is not None:
                        narration = rule.narration
                    if rule.flag is not None:
                        flag = rule.flag
                    tags.update(rule.tags)
            if counter is None:
                counter = profile.default_account
            if counter is None:
                raise _Bad("no account for the other side: no rule picks one and there is no default_account")
            tx = Transaction(
                date=on,
                payee=payee,
                narration=narration,
                postings=[Posting(profile.account, amount), Posting(counter, -amount)],
                tags=tuple(sorted(tags)),
                flag=flag,
                id=None,
            )
            built.append(tx)
        except _Bad as e:
            errors.append((row, str(e)))

    have = Counter()
    for tx in existing or ():
        k = _key(tx, profile.account)
        if k is not None:
            have[k] += 1
    seen = Counter()
    result = ImportResult(errors=errors)
    for tx in built:
        k = _key(tx, profile.account)
        seen[k] += 1
        if seen[k] <= have[k]:
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result

"""Budgets: allowances per calendar period and how spending compares."""

import datetime
import decimal
import re
from fractions import Fraction

from tallybook.dates import Period, last_day
from tallybook.errors import ValidationError
from tallybook.money import Money, round_div

__all__ = ["Budget", "BudgetError", "BudgetLine", "budget_status"]

PERIOD_KINDS = ("month", "quarter", "year")
_KIND_ORDER = {"month": 0, "quarter": 1, "year": 2}
_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class BudgetError(ValidationError):
    """A malformed budget or budget request."""


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _check_pattern(pattern):
    if not isinstance(pattern, str):
        raise BudgetError("invalid budget pattern %r: expected text" % (pattern,))
    if not pattern:
        raise BudgetError("invalid budget pattern '': it is empty")
    for seg in pattern.split(":"):
        if seg != "*" and not _SEGMENT_RE.fullmatch(seg):
            raise BudgetError("invalid budget pattern '%s': each segment is '*' or an account name segment"
                              % pattern)


def _pattern_matches(segs, path):
    parts = path.split(":")
    if len(parts) < len(segs):
        return False
    return all(s == "*" or s == p for s, p in zip(segs, parts))


class Budget:
    __slots__ = ("_pattern", "_period_kind", "_amount", "_start")

    def __init__(self, pattern, period_kind, amount, start):
        _check_pattern(pattern)
        if not isinstance(period_kind, str) or period_kind not in PERIOD_KINDS:
            raise BudgetError("invalid budget period kind %r: expected month, quarter or year" % (period_kind,))
        if not isinstance(amount, Money):
            raise BudgetError("invalid budget amount %r: expected Money" % (amount,))
        if amount.minor <= 0:
            raise BudgetError("invalid budget amount %s: it must be greater than zero" % (amount,))
        if not _is_date(start):
            raise BudgetError("invalid budget start %r: expected a date" % (start,))
        object.__setattr__(self, "_pattern", pattern)
        object.__setattr__(self, "_period_kind", period_kind)
        object.__setattr__(self, "_amount", amount)
        object.__setattr__(self, "_start", start)

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    amount = property(lambda self: self._amount)
    start = property(lambda self: self._start)

    def __setattr__(self, name, value):
        raise AttributeError("Budget is immutable")

    def __delattr__(self, name):
        raise AttributeError("Budget is immutable")

    def __reduce__(self):
        return (Budget, (self._pattern, self._period_kind, self._amount, self._start))

    def _key(self):
        return (self._pattern, self._period_kind, self._amount, self._start)

    def __eq__(self, other):
        if not isinstance(other, Budget):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "Budget(%r, %r, %r, %r)" % self._key()


def _calendar_period(d, kind):
    if kind == "month":
        return datetime.date(d.year, d.month, 1), datetime.date(d.year, d.month, last_day(d.year, d.month))
    if kind == "quarter":
        mo = (d.month - 1) // 3 * 3 + 1
        return datetime.date(d.year, mo, 1), datetime.date(d.year, mo + 2, last_day(d.year, mo + 2))
    return datetime.date(d.year, 1, 1), datetime.date(d.year, 12, 31)


def _allowance_fraction(budget, period):
    """Sum of overlapping-days / days for each calendar period in force, or None if not in force."""
    first_start, _ = _calendar_period(budget.start, budget.period_kind)
    if first_start > period.end:
        return None
    total = Fraction(0)
    d = max(first_start, period.start)
    while d <= period.end:
        ps, pe = _calendar_period(d, budget.period_kind)
        lo = max(ps, period.start)
        hi = min(pe, period.end)
        total += Fraction((hi - lo).days + 1, (pe - ps).days + 1)
        if pe >= period.end:
            break
        d = pe + datetime.timedelta(days=1)
    return total


def _percent(actual, allowance):
    if allowance == 0:
        tenths = 0 if actual == 0 else 1000
    else:
        tenths = round_div(actual * 1000, allowance)
    sign = "-" if tenths < 0 else ""
    q, r = divmod(abs(tenths), 10)
    return decimal.Decimal("%s%d.%d" % (sign, q, r))


class BudgetLine:
    __slots__ = ("_pattern", "_period_kind", "_budget", "_actual", "_remaining", "_percent", "_over", "_accounts")
    _FIELDS = ("pattern", "period_kind", "budget", "actual", "remaining", "percent", "over", "accounts")

    def __init__(self, pattern, period_kind, budget, actual, remaining, percent, over, accounts):
        for name, value in zip(self._FIELDS, (pattern, period_kind, budget, actual, remaining, percent, over,
                                              tuple(tuple(a) for a in accounts))):
            object.__setattr__(self, "_" + name, value)

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    budget = property(lambda self: self._budget)
    actual = property(lambda self: self._actual)
    remaining = property(lambda self: self._remaining)
    percent = property(lambda self: self._percent)
    over = property(lambda self: self._over)
    accounts = property(lambda self: self._accounts)

    def __setattr__(self, name, value):
        raise AttributeError("BudgetLine is immutable")

    def __delattr__(self, name):
        raise AttributeError("BudgetLine is immutable")

    def _key(self):
        return tuple(getattr(self, "_" + f) for f in self._FIELDS)

    def __reduce__(self):
        return (BudgetLine, self._key())

    def __eq__(self, other):
        if not isinstance(other, BudgetLine):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "BudgetLine(%s)" % ", ".join("%s=%r" % (f, getattr(self, f)) for f in self._FIELDS)

    def to_dict(self):
        def money(m):
            return {"amount": m.amount_str(), "currency": m.currency}
        return {
            "pattern": self._pattern,
            "period_kind": self._period_kind,
            "budget": money(self._budget),
            "actual": money(self._actual),
            "remaining": money(self._remaining),
            "percent": str(self._percent),
            "over": bool(self._over),
            "accounts": [{"account": a, "amount": money(m)} for a, m in self._accounts],
        }


def budget_status(budgets, ledger, period):
    if isinstance(budgets, (str, bytes)):
        raise BudgetError("budgets must be a list of Budget")
    try:
        budgets = list(budgets)
    except TypeError:
        raise BudgetError("budgets must be a list of Budget") from None
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a budget: %r" % (b,))
    if not isinstance(period, Period):
        raise BudgetError("invalid period %r: expected a Period" % (period,))

    # Expense postings within the period, per account and currency.
    spending = {}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        if p.amount is None or p.account.split(":", 1)[0] != "Expenses":
            continue
        key = (p.account, p.amount.currency)
        spending[key] = spending.get(key, 0) + p.amount.minor

    order = sorted(range(len(budgets)),
                   key=lambda i: (budgets[i].pattern, _KIND_ORDER[budgets[i].period_kind], budgets[i].start, i))
    lines = []
    for i in order:
        b = budgets[i]
        frac = _allowance_fraction(b, period)
        if frac is None:
            continue
        code = b.amount.currency
        scaled = frac * b.amount.minor
        allowance = round_div(scaled.numerator, scaled.denominator)
        segs = b.pattern.split(":")
        per_account = {}
        for (account, cur), minor in spending.items():
            if cur == code and _pattern_matches(segs, account):
                per_account[account] = per_account.get(account, 0) + minor
        actual = sum(per_account.values())
        accounts = tuple((a, Money(v, code)) for a, v in sorted(per_account.items()) if v != 0)
        lines.append(BudgetLine(b.pattern, b.period_kind, Money(allowance, code), Money(actual, code),
                                Money(allowance - actual, code), _percent(actual, allowance),
                                actual > allowance, accounts))
    return lines

