    """

    __slots__ = ("_kind", "_value")

    def __init__(self, kind, value=None):
        object.__setattr__(self, "_kind", kind)
        object.__setattr__(self, "_value", value)

    kind = property(lambda self: self._kind)
    value = property(lambda self: self._value)

    def __setattr__(self, name, value):
        raise AttributeError("Schedule is immutable")

    def __delattr__(self, name):
        raise AttributeError("Schedule is immutable")

    def __reduce__(self):
        return (parse_schedule, (str(self),))

    def __eq__(self, other):
        if not isinstance(other, Schedule):
            return NotImplemented
        return self._kind == other._kind and self._value == other._value

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash((self._kind, self._value))

    def __str__(self):
        k, v = self._kind, self._value
        if k == "daily":
            return "daily"
        if k == "weekly":
            return "weekly on %s" % _WEEKDAYS[v]
        if k == "monthly":
            return "monthly on %s" % v
        if k == "yearly":
            return "yearly on %02d-%02d" % v
        n, unit, frm = v
        return "every %d %s from %s" % (n, unit if n == 1 else unit + "s", frm.isoformat())

    def __repr__(self):
        return "Schedule(%r)" % str(self)

    # ------------------------------------------------------------ index model
    # The schedule's dates are indexed by integers k, ascending in k. _date(k)
    # returns the k-th date or None when it is outside the date range;
    # _index_ge(d) returns the smallest index whose date is >= d.

    def _date(self, k):
        kd, v = self._kind, self._value
        try:
            if kd == "daily":
                if not _MIN_ORD <= k <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(k)
            if kd == "weekly":
                o = 7 * k + 1 + v
                if not _MIN_ORD <= o <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            if kd == "monthly":
                y, m = divmod(k, 12)
                m += 1
                if not 1 <= y <= 9999:
                    return None
                ld = last_day(y, m)
                return datetime.date(y, m, ld if v == "last" else min(v, ld))
            if kd == "yearly":
                if not 1 <= k <= 9999:
                    return None
                mo, dd = v
                return datetime.date(k, mo, min(dd, last_day(k, mo)))
            n, unit, frm = v
            if k < 0:
                return None
            if unit in ("day", "week"):
                o = frm.toordinal() + k * n * (7 if unit == "week" else 1)
                if o > _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            months = k * n * (12 if unit == "year" else 1)
            if frm.year * 12 + frm.month - 1 + months > 9999 * 12 + 11:
                return None
            return add_months(frm, months)
        except (OverflowError, ValueError, DateError):
            return None

    def _index_ge(self, d):
        kd, v = self._kind, self._value
        if kd == "daily":
            return d.toordinal()
        if kd == "weekly":
            return _ceil_div(d.toordinal() - 1 - v, 7)
        if kd == "monthly":
            k = d.year * 12 + d.month - 1
        elif kd == "yearly":
            k = d.year
        else:
            n, unit, frm = v
            if d <= frm:
                return 0
            if unit in ("day", "week"):
                step = n * (7 if unit == "week" else 1)
                return _ceil_div(d.toordinal() - frm.toordinal(), step)
            step = n * (12 if unit == "year" else 1)
            diff = (d.year * 12 + d.month) - (frm.year * 12 + frm.month)
            k = max(0, diff // step)
            while k > 0:
                prev = self._date(k - 1)
                if prev is None or prev < d:
                    break
                k -= 1
        # Step forward while the k-th date is before d (at most a couple of times).
        while True:
            x = self._date(k)
            if x is None or x >= d:
                return k
            k += 1

    def _iter(self, lo, hi=None, kmax=None):
        """Dates of the schedule from index lo on, up to date hi and index kmax."""
        k = lo
        while kmax is None or k <= kmax:
            x = self._date(k)
            if x is None or (hi is not None and x > hi):
                return
            yield x
            k += 1

    def between(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise RecurringError("between needs two dates, got %r and %r" % (start, end))
        if end < start:
            return []
        return list(self._iter(self._index_ge(start), end))


def _bad(text):
    shown = "'%s'" % text if isinstance(text, str) else repr(text)
    return RecurringError("invalid schedule %s: expected one of %s" % (shown, SHAPES))


def parse_schedule(text):
    if isinstance(text, Schedule):
        return text
    if not isinstance(text, str):
        raise _bad(text)
    words = text.lower().split()
    if words == ["daily"]:
        return Schedule("daily")
    if len(words) == 3 and words[1] == "on":
        kind, _, arg = words
        if kind == "weekly" and arg in _WEEKDAYS:
            return Schedule("weekly", _WEEKDAYS.index(arg))
        if kind == "monthly":
            if arg == "last":
                return Schedule("monthly", "last")
            if re.fullmatch(r"[0-9]{1,2}", arg) and 1 <= int(arg) <= 31:
                return Schedule("monthly", int(arg))
        if kind == "yearly":
            m = re.fullmatch(r"([0-9]{2})-([0-9]{2})", arg)
            if m:
                mo, dd = int(m.group(1)), int(m.group(2))
                if 1 <= mo <= 12 and 1 <= dd <= last_day(2024, mo):
                    return Schedule("yearly", (mo, dd))
    if len(words) == 5 and words[0] == "every" and words[3] == "from":
        n, unit, frm = words[1], words[2], words[4]
        if re.fullmatch(r"[0-9]+", n) and int(n) >= 1 and unit in _UNITS:
            try:
                d = parse_date(frm)
            except DateError:
                d = None
            if d is not None:
                return Schedule("every", (int(n), _UNITS[unit], d))
    raise _bad(text)


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return "%d%s" % (n, suffix)


def describe(schedule):
    s = parse_schedule(schedule)
    k, v = s.kind, s.value
    if k == "daily":
        return "every day"
    if k == "weekly":
        return "every %s" % _WEEKDAY_NAMES[v]
    if k == "monthly":
        if v == "last":
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(v)
    if k == "yearly":
        return "every year on %d %s" % (v[1], _MONTH_NAMES[v[0] - 1])
    n, unit, frm = v
    if n == 1:
        return "every %s from %s" % (unit, frm.isoformat())
    return "every %d %ss from %s" % (n, unit, frm.isoformat())


class Recurring:
    __slots__ = ("_name", "_schedule", "_template", "_start", "_end", "_count")

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise RecurringError("invalid recurring name %s: use ASCII letters, digits, '-' and '_', "
                                 "not starting with '-' or '_'"
                                 % ("'%s'" % name if isinstance(name, str) else repr(name)))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("invalid schedule %r: expected a Schedule or text" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("invalid template %r: expected a Transaction" % (template,))
        if not _is_date(start):
            raise RecurringError("invalid start %r: expected a date" % (start,))
        if end is not None:
            if not _is_date(end):
                raise RecurringError("invalid end %r: expected a date" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (end.isoformat(), start.isoformat()))
        if count is not None and (not is_int(count) or count < 1):
            raise RecurringError("invalid count %r: expected a whole number of at least 1" % (count,))
        object.__setattr__(self, "_name", name)
        object.__setattr__(self, "_schedule", schedule)
        object.__setattr__(self, "_template", template)
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)
        object.__setattr__(self, "_count", count)

    name = property(lambda self: self._name)
    schedule = property(lambda self: self._schedule)
    template = property(lambda self: self._template)
    start = property(lambda self: self._start)
    end = property(lambda self: self._end)
    count = property(lambda self: self._count)

    def __setattr__(self, name, value):
        raise AttributeError("Recurring is immutable")

    def __delattr__(self, name):
        raise AttributeError("Recurring is immutable")

    def _key(self):
        return (self._name, self._schedule, self._template, self._start, self._end, self._count)

    def __reduce__(self):
        return (Recurring, self._key())

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    __hash__ = None  # the template is a mutable Transaction

    def __repr__(self):
        return "Recurring(%r, %r, %r, start=%r, end=%r, count=%r)" % (
            self._name, str(self._schedule), self._template, self._start, self._end, self._count)


def _check_rec(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))


def _series(rec, lo_date, hi_date):
    """Dates of rec's series that are >= lo_date and <= hi_date (hi_date may be None)."""
    s = rec.schedule
    if rec.end is not None and (hi_date is None or rec.end < hi_date):
        hi_date = rec.end
    kmax = None
    if rec.count is not None:
        kmax = s._index_ge(rec.start) + rec.count - 1
    lo = s._index_ge(max(lo_date, rec.start))
    return s._iter(lo, hi_date, kmax)


def occurrences(rec, start, end):
    _check_rec(rec)
    if not _is_date(start) or not _is_date(end):
        raise RecurringError("occurrences needs two dates, got %r and %r" % (start, end))
    if end < start:
        return []
    return list(_series(rec, start, end))


def next_occurrence(rec, after):
    _check_rec(rec)
    if not _is_date(after):
        raise RecurringError("invalid date %r" % (after,))
    if after >= datetime.date.max:
        return None
    for d in _series(rec, after + datetime.timedelta(days=1), None):
        return d
    return None


def instantiate(rec, on):
    _check_rec(rec)
    if not _is_date(on):
        raise RecurringError("invalid date %r" % (on,))
    t = rec.template
    tags = tuple(sorted(set(tuple(t.tags) + ("recurring",))))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    if isinstance(recs, (str, bytes)):
        raise RecurringError("expand needs a list of Recurring")
    recs = list(recs)
    for r in recs:
        _check_rec(r)
    if not _is_date(start) or not _is_date(end):
        raise RecurringError("expand needs two dates, got %r and %r" % (start, end))
    items = []
    for i, r in enumerate(recs):
        for d in occurrences(r, start, end):
            items.append((d, r.name, i))
    items.sort()
    return [instantiate(recs[i], d) for d, _, i in items]

"""Reports: trial balance, balance sheet, income statement, cash flow, register, net worth."""

import datetime

from tallybook.accounts import ROOT_TYPES
from tallybook.currency import currency as _currency
from tallybook.dates import Period, periods
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_csv
from tallybook.ledger import Ledger
from tallybook.money import Money, round_div

__all__ = ["trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth",
           "render_text", "report_to_csv", "ReportError"]

REPORT_KINDS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
STEPS = ("week", "month", "quarter", "year")


class ReportError(ValidationError):
    """A report that cannot be made or drawn."""


# ---------------------------------------------------------------- helpers
def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _date_text(d):
    return None if d is None else "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _check_ledger(ledger):
    if not isinstance(ledger, Ledger):
        raise ReportError("not a ledger: %r" % (ledger,))


def _check_as_of(as_of):
    if as_of is not None and not _is_date(as_of):
        raise ReportError("invalid date %r" % (as_of,))


def _check_period(period, optional=False):
    if period is None and optional:
        return
    if not isinstance(period, Period):
        raise ReportError("invalid period %r" % (period,))


def _check_convert_to(convert_to):
    if convert_to is not None:
        _currency(convert_to)  # CurrencyError as it is


def _type_of(path):
    return ROOT_TYPES.get(path.split(":", 1)[0])


def _m(minor, code):
    return money_to_dict(Money(minor, code))


def _money_list(sums, keep_zero):
    """A list of money dicts from {currency: minor}, sorted by currency."""
    return [_m(v, c) for c, v in sorted(sums.items()) if keep_zero or v != 0]


def _account_lines(sums):
    """Sorted (account, currency, minor) for non-zero entries of {(account, currency): minor}."""
    return [(a, c, v) for (a, c), v in sorted(sums.items()) if v != 0]


def _add(d, key, value):
    d[key] = d.get(key, 0) + value


def _percent(part, total):
    if total == 0:
        return "0.0"
    if total < 0:
        part, total = -part, -total
    tenths = round_div(part * 1000, total)
    if tenths == 0:
        return "0.0"
    sign = "-" if tenths < 0 else ""
    a = abs(tenths)
    return "%s%d.%d" % (sign, a // 10, a % 10)


def _convert(ledger, minor, code, convert_to, on):
    return ledger.rates.convert(Money(minor, code), convert_to, on)


# ------------------------------------------------------------ trial balance
def trial_balance(ledger, as_of=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    sums = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        _add(sums, (p.account, p.amount.currency), p.amount.minor)
    accounts = []
    totals = {}
    for account, cur, v in _account_lines(sums):
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            t[0] += v
        else:
            t[1] += -v
        accounts.append({"account": account, "type": _type_of(account),
                         "debit": _m(v, cur) if v > 0 else None,
                         "credit": _m(-v, cur) if v < 0 else None})
    return {"report": "trial_balance", "as_of": _date_text(as_of), "accounts": accounts,
            "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                       for c, (d, cr) in sorted(totals.items())]}


# ------------------------------------------------------------ balance sheet
def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    if convert_to is not None and as_of is None:
        raise ReportError("converting needs a date: give as_of with convert_to")
    _check_convert_to(convert_to)
    sections = {"asset": {}, "liability": {}, "equity": {}}
    retained = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        t = _type_of(p.account)
        cur, v = p.amount.currency, p.amount.minor
        if t == "asset":
            _add(sections["asset"], (p.account, cur), v)
        elif t in ("liability", "equity"):
            _add(sections[t], (p.account, cur), -v)
        elif t in ("income", "expense"):
            _add(retained, cur, -v)

    def section(kind):
        lines = []
        total = {}
        for account, cur, v in _account_lines(sections[kind]):
            if convert_to is None:
                lines.append({"account": account, "balance": _m(v, cur)})
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": account, "balance": money_to_dict(conv), "original": _m(v, cur)})
                _add(total, convert_to, conv.minor)
        return lines, total

    a_lines, a_total = section("asset")
    l_lines, l_total = section("liability")
    e_lines, e_total = section("equity")
    if convert_to is None:
        re_list = _money_list(retained, keep_zero=False)
        for c, v in retained.items():
            if v != 0:
                _add(e_total, c, v)
    else:
        nonzero = [(c, v) for c, v in sorted(retained.items()) if v != 0]
        re_list = []
        if nonzero:
            s = 0
            for c, v in nonzero:
                s += _convert(ledger, v, c, convert_to, as_of).minor
            re_list = [_m(s, convert_to)]
            _add(e_total, convert_to, s)
        for t in (a_total, l_total, e_total):
            t.setdefault(convert_to, 0)
    curs = set(a_total) | set(l_total) | set(e_total)
    balanced = all(a_total.get(c, 0) == l_total.get(c, 0) + e_total.get(c, 0) for c in curs)
    return {"report": "balance_sheet", "as_of": _date_text(as_of), "currency": convert_to,
            "assets": {"accounts": a_lines, "total": _money_list(a_total, True)},
            "liabilities": {"accounts": l_lines, "total": _money_list(l_total, True)},
            "equity": {"accounts": e_lines, "retained_earnings": re_list, "total": _money_list(e_total, True)},
            "balanced": balanced}


# --------------------------------------------------------- income statement
def income_statement(ledger, period, convert_to=None):
    _check_ledger(ledger)
    _check_period(period)
    _check_convert_to(convert_to)
    sums = {"income": {}, "expense": {}}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        t = _type_of(p.account)
        if t == "income":
            _add(sums["income"], (p.account, p.amount.currency), -p.amount.minor)
        elif t == "expense":
            _add(sums["expense"], (p.account, p.amount.currency), p.amount.minor)

    def section(kind):
        raw = _account_lines(sums[kind])
        total = {}
        items = []
        for account, cur, v in raw:
            if convert_to is None:
                items.append((account, cur, v, None))
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, period.end)
                items.append((account, convert_to, conv.minor, _m(v, cur)))
                _add(total, convert_to, conv.minor)
        if convert_to is not None:
            total.setdefault(convert_to, 0)
        lines = []
        for account, cur, v, original in items:
            line = {"account": account, "amount": _m(v, cur), "percent": _percent(v, total[cur])}
            if original is not None:
                line["original"] = original
            lines.append(line)
        return lines, total

    i_lines, i_total = section("income")
    e_lines, e_total = section("expense")
    net = {c: i_total.get(c, 0) - e_total.get(c, 0) for c in set(i_total) | set(e_total)}
    return {"report": "income_statement", "start": _date_text(period.start), "end": _date_text(period.end),
            "currency": convert_to,
            "income": {"accounts": i_lines, "total": _money_list(i_total, True)},
            "expenses": {"accounts": e_lines, "total": _money_list(e_total, True)},
            "net": _money_list(net, True)}


# ----------------------------------------------------------------- cashflow
def cashflow(ledger, period):
    _check_ledger(ledger)
    _check_period(period)
    opening, closing, flows = {}, {}, {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                cur = p.amount.currency
                closing.setdefault(cur, 0)
                opening.setdefault(cur, 0)
                closing[cur] += p.amount.minor
                if tx.date < period.start:
                    opening[cur] += p.amount.minor
        if tx.date < period.start:
            continue
        asset_sum = {}
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if _type_of(p.account) != "asset" and asset_sum.get(p.amount.currency, 0) != 0:
                _add(flows, (p.account, p.amount.currency), -p.amount.minor)
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for account, cur, v in _account_lines(flows):
        if v > 0:
            inflows.append({"account": account, "amount": _m(v, cur)})
            total_in[cur] = total_in.get(cur, 0) + v
        else:
            outflows.append({"account": account, "amount": _m(-v, cur)})
            total_out[cur] = total_out.get(cur, 0) - v
    net = {c: total_in.get(c, 0) - total_out.get(c, 0) for c in closing}
    return {"report": "cashflow", "start": _date_text(period.start), "end": _date_text(period.end),
            "opening": _money_list(opening, True), "inflows": inflows, "outflows": outflows,
            "total_in": _money_list(total_in, True), "total_out": _money_list(total_out, True),
            "net": _money_list(net, True), "closing": _money_list(closing, True)}


# ----------------------------------------------------------------- register
def register(ledger, account, period=None, rollup=False):
    _check_ledger(ledger)
    _check_period(period, optional=True)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be true or false, got %r" % (rollup,))
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account %s" % ("'%s'" % account if isinstance(account, str) else repr(account)))
    prefix = account + ":"
    opening, running, rows = {}, {}, []
    for tx in ledger.transactions():
        if period is not None and tx.date > period.end:
            continue
        for p in tx.postings:
            if not (p.account == account or (rollup and p.account.startswith(prefix))):
                continue
            cur, v = p.amount.currency, p.amount.minor
            opening.setdefault(cur, 0)
            running.setdefault(cur, 0)
            running[cur] += v
            if period is not None and tx.date < period.start:
                opening[cur] += v
                continue
            rows.append({"date": _date_text(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                         "account": p.account, "amount": _m(v, cur), "balance": _m(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": rollup,
            "start": _date_text(period.start) if period is not None else None,
            "end": _date_text(period.end) if period is not None else None,
            "opening": _money_list(opening, True), "rows": rows, "closing": _money_list(running, True)}


# ---------------------------------------------------------------- net worth
def net_worth(ledger, period, step="month"):
    _check_ledger(ledger)
    _check_period(period)
    if not isinstance(step, str) or step not in STEPS:
        raise ReportError("unknown step %r: expected week, month, quarter or year" % (step,))
    steps = periods(period.start, period.end, step)
    txs = ledger.transactions()
    points = []
    for st in steps:
        d = st.end
        assets, liabilities = {}, {}
        for tx in txs:
            if tx.date > d:
                break
            for p in tx.postings:
                t = _type_of(p.account)
                if t in ("asset", "liability"):
                    cur = p.amount.currency
                    assets.setdefault(cur, 0)
                    liabilities.setdefault(cur, 0)
                    if t == "asset":
                        assets[cur] += p.amount.minor
                    else:
                        liabilities[cur] -= p.amount.minor
        net = {c: assets[c] - liabilities[c] for c in assets}
        points.append({"date": _date_text(d), "assets": _money_list(assets, True),
                       "liabilities": _money_list(liabilities, True), "net": _money_list(net, True)})
    return {"report": "net_worth", "start": _date_text(period.start), "end": _date_text(period.end),
            "step": step, "points": points}


# --------------------------------------------------------------- rendering
def _kind(report):
    if not isinstance(report, dict) or report.get("report") not in REPORT_KINDS:
        raise ReportError("not a report: %r" % (report,))
    return report["report"]


def _mt(m):
    return "%s %s" % (m["amount"], m["currency"])


def _blocks(width, *blocks):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def _text_trial_balance(r):
    title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
    rows = [[a["account"], a["type"], _mt(a["debit"]) if a["debit"] else "",
             _mt(a["credit"]) if a["credit"] else ""] for a in r["accounts"]]
    rows += [["Total", "", _mt(t["debit"]), _mt(t["credit"])] for t in r["totals"]]
    return title, ["Account", "Type", "Debit", "Credit"], rows, "llrr"


def _text_balance_sheet(r):
    title = "Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet"
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label, extra=()):
        sec = r[key]
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["balance"])] for a in sec["accounts"]]
        b += list(extra)
        b += [[total_label, _mt(m)] for m in sec["total"]]
        return b

    rows = _blocks(2, block("assets", "Assets", "Total assets"),
                   block("liabilities", "Liabilities", "Total liabilities"),
                   block("equity", "Equity", "Total equity",
                         [["  Retained earnings", _mt(m)] for m in r["equity"]["retained_earnings"]]))
    return title, ["Account", "Balance"], rows, "lr"


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label):
        sec = r[key]
        b = [[heading, "", ""]]
        b += [["  " + a["account"], _mt(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
        b += [[total_label, _mt(m), ""] for m in sec["total"]]
        return b

    rows = _blocks(3, block("income", "Income", "Total income"),
                   block("expenses", "Expenses", "Total expenses"),
                   [["Net income", _mt(m), ""] for m in r["net"]])
    return title, ["Account", "Amount", "Percent"], rows, "lrr"


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])

    def block(lines, totals, heading, total_label):
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["amount"])] for a in lines]
        b += [[total_label, _mt(m)] for m in totals]
        return b

    rows = _blocks(2, [["Opening balance", _mt(m)] for m in r["opening"]],
                   block(r["inflows"], r["total_in"], "Money in", "Total money in"),
                   block(r["outflows"], r["total_out"], "Money out", "Total money out"),
                   [["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]])
    return title, ["Account", "Amount"], rows, "lr"


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for p in r["points"]:
        if not p["assets"]:
            rows.append([p["date"], "", "", ""])
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], _mt(a), _mt(l), _mt(n)])
    return title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr"


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else str(row["id"]), row["payee"], row["account"],
                     _mt(row["amount"]), _mt(row["balance"])])
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr"


_TEXT = {"trial_balance": _text_trial_balance, "balance_sheet": _text_balance_sheet,
         "income_statement": _text_income_statement, "cashflow": _text_cashflow,
         "net_worth": _text_net_worth, "register": _text_register}


def render_text(report):
    kind = _kind(report)
    try:
        title, headers, rows, align = _TEXT[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return title + "\n\n" + render_table(headers, rows, align)


# --------------------------------------------------------------------- CSV
def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        m = a["debit"] or a["credit"]
        rows.append([a["account"], a["type"], m["currency"], a["debit"]["amount"] if a["debit"] else "",
                     a["credit"]["amount"] if a["credit"] else ""])
    return ["account", "type", "currency", "debit", "credit"], rows


def _csv_balance_sheet(r):
    rows = []
    for key in ("assets", "liabilities", "equity"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
    for m in r["equity"]["retained_earnings"]:
        rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
    return ["section", "account", "currency", "balance"], rows


def _csv_income_statement(r):
    rows = []
    for key in ("income", "expenses"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
    return ["section", "account", "currency", "amount", "percent"], rows


def _csv_cashflow(r):
    rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
    rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
    rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
    rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
    return ["section", "account", "currency", "amount"], rows


def _csv_register(r):
    rows = [[row["date"], "" if row["id"] is None else row["id"], row["payee"], row["narration"], row["account"],
             row["amount"]["currency"], row["amount"]["amount"], row["balance"]["amount"]] for row in r["rows"]]
    return ["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows


def _csv_net_worth(r):
    rows = []
    for p in r["points"]:
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return ["date", "currency", "assets", "liabilities", "net"], rows


_CSV = {"trial_balance": _csv_trial_balance, "balance_sheet": _csv_balance_sheet,
        "income_statement": _csv_income_statement, "cashflow": _csv_cashflow,
        "net_worth": _csv_net_worth, "register": _csv_register}


def report_to_csv(report):
    kind = _kind(report)
    try:
        headers, rows = _CSV[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return to_csv(headers, rows)

"""Reports: trial balance, balance sheet, income statement, cash flow, register, net worth."""

import datetime

from tallybook.accounts import ROOT_TYPES
from tallybook.currency import currency as _currency
from tallybook.dates import Period, periods
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_csv
from tallybook.ledger import Ledger
from tallybook.money import Money, round_div

__all__ = ["trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth",
           "render_text", "report_to_csv", "ReportError"]

REPORT_KINDS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
STEPS = ("week", "month", "quarter", "year")


class ReportError(ValidationError):
    """A report that cannot be made or drawn."""


# ---------------------------------------------------------------- helpers
def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _date_text(d):
    return None if d is None else "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _check_ledger(ledger):
    if not isinstance(ledger, Ledger):
        raise ReportError("not a ledger: %r" % (ledger,))


def _check_as_of(as_of):
    if as_of is not None and not _is_date(as_of):
        raise ReportError("invalid date %r" % (as_of,))


def _check_period(period, optional=False):
    if period is None and optional:
        return
    if not isinstance(period, Period):
        raise ReportError("invalid period %r" % (period,))


def _check_convert_to(convert_to):
    if convert_to is not None:
        _currency(convert_to)  # CurrencyError as it is


def _type_of(path):
    return ROOT_TYPES.get(path.split(":", 1)[0])


def _m(minor, code):
    return money_to_dict(Money(minor, code))


def _money_list(sums, keep_zero):
    """A list of money dicts from {currency: minor}, sorted by currency."""
    return [_m(v, c) for c, v in sorted(sums.items()) if keep_zero or v != 0]


def _account_lines(sums):
    """Sorted (account, currency, minor) for non-zero entries of {(account, currency): minor}."""
    return [(a, c, v) for (a, c), v in sorted(sums.items()) if v != 0]


def _add(d, key, value):
    d[key] = d.get(key, 0) + value


def _percent(part, total):
    if total == 0:
        return "0.0"
    if total < 0:
        part, total = -part, -total
    tenths = round_div(part * 1000, total)
    if tenths == 0:
        return "0.0"
    sign = "-" if tenths < 0 else ""
    a = abs(tenths)
    return "%s%d.%d" % (sign, a // 10, a % 10)


def _convert(ledger, minor, code, convert_to, on):
    return ledger.rates.convert(Money(minor, code), convert_to, on)


# ------------------------------------------------------------ trial balance
def trial_balance(ledger, as_of=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    sums = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        _add(sums, (p.account, p.amount.currency), p.amount.minor)
    accounts = []
    totals = {}
    for account, cur, v in _account_lines(sums):
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            t[0] += v
        else:
            t[1] += -v
        accounts.append({"account": account, "type": _type_of(account),
                         "debit": _m(v, cur) if v > 0 else None,
                         "credit": _m(-v, cur) if v < 0 else None})
    return {"report": "trial_balance", "as_of": _date_text(as_of), "accounts": accounts,
            "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                       for c, (d, cr) in sorted(totals.items())]}


# ------------------------------------------------------------ balance sheet
def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    if convert_to is not None and as_of is None:
        raise ReportError("converting needs a date: give as_of with convert_to")
    _check_convert_to(convert_to)
    sections = {"asset": {}, "liability": {}, "equity": {}}
    retained = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        t = _type_of(p.account)
        cur, v = p.amount.currency, p.amount.minor
        if t == "asset":
            _add(sections["asset"], (p.account, cur), v)
        elif t in ("liability", "equity"):
            _add(sections[t], (p.account, cur), -v)
        elif t in ("income", "expense"):
            _add(retained, cur, -v)

    def section(kind):
        lines = []
        total = {}
        for account, cur, v in _account_lines(sections[kind]):
            if convert_to is None:
                lines.append({"account": account, "balance": _m(v, cur)})
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": account, "balance": money_to_dict(conv), "original": _m(v, cur)})
                _add(total, convert_to, conv.minor)
        return lines, total

    a_lines, a_total = section("asset")
    l_lines, l_total = section("liability")
    e_lines, e_total = section("equity")
    if convert_to is None:
        re_list = _money_list(retained, keep_zero=False)
        for c, v in retained.items():
            if v != 0:
                _add(e_total, c, v)
    else:
        nonzero = [(c, v) for c, v in sorted(retained.items()) if v != 0]
        re_list = []
        if nonzero:
            s = 0
            for c, v in nonzero:
                s += _convert(ledger, v, c, convert_to, as_of).minor
            re_list = [_m(s, convert_to)]
            _add(e_total, convert_to, s)
        for t in (a_total, l_total, e_total):
            t.setdefault(convert_to, 0)
    curs = set(a_total) | set(l_total) | set(e_total)
    balanced = all(a_total.get(c, 0) == l_total.get(c, 0) + e_total.get(c, 0) for c in curs)
    return {"report": "balance_sheet", "as_of": _date_text(as_of), "currency": convert_to,
            "assets": {"accounts": a_lines, "total": _money_list(a_total, True)},
            "liabilities": {"accounts": l_lines, "total": _money_list(l_total, True)},
            "equity": {"accounts": e_lines, "retained_earnings": re_list, "total": _money_list(e_total, True)},
            "balanced": balanced}


# --------------------------------------------------------- income statement
def income_statement(ledger, period, convert_to=None):
    _check_ledger(ledger)
    _check_period(period)
    _check_convert_to(convert_to)
    sums = {"income": {}, "expense": {}}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        t = _type_of(p.account)
        if t == "income":
            _add(sums["income"], (p.account, p.amount.currency), -p.amount.minor)
        elif t == "expense":
            _add(sums["expense"], (p.account, p.amount.currency), p.amount.minor)

    def section(kind):
        raw = _account_lines(sums[kind])
        total = {}
        items = []
        for account, cur, v in raw:
            if convert_to is None:
                items.append((account, cur, v, None))
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, period.end)
                items.append((account, convert_to, conv.minor, _m(v, cur)))
                _add(total, convert_to, conv.minor)
        if convert_to is not None:
            total.setdefault(convert_to, 0)
        lines = []
        for account, cur, v, original in items:
            line = {"account": account, "amount": _m(v, cur), "percent": _percent(v, total[cur])}
            if original is not None:
                line["original"] = original
            lines.append(line)
        return lines, total

    i_lines, i_total = section("income")
    e_lines, e_total = section("expense")
    net = {c: i_total.get(c, 0) - e_total.get(c, 0) for c in set(i_total) | set(e_total)}
    return {"report": "income_statement", "start": _date_text(period.start), "end": _date_text(period.end),
            "currency": convert_to,
            "income": {"accounts": i_lines, "total": _money_list(i_total, True)},
            "expenses": {"accounts": e_lines, "total": _money_list(e_total, True)},
            "net": _money_list(net, True)}


# ----------------------------------------------------------------- cashflow
def cashflow(ledger, period):
    _check_ledger(ledger)
    _check_period(period)
    opening, closing, flows = {}, {}, {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                cur = p.amount.currency
                closing.setdefault(cur, 0)
                opening.setdefault(cur, 0)
                closing[cur] += p.amount.minor
                if tx.date < period.start:
                    opening[cur] += p.amount.minor
        if tx.date < period.start:
            continue
        asset_sum = {}
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if _type_of(p.account) != "asset" and asset_sum.get(p.amount.currency, 0) != 0:
                _add(flows, (p.account, p.amount.currency), -p.amount.minor)
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for account, cur, v in _account_lines(flows):
        if v > 0:
            inflows.append({"account": account, "amount": _m(v, cur)})
            total_in[cur] = total_in.get(cur, 0) + v
        else:
            outflows.append({"account": account, "amount": _m(-v, cur)})
            total_out[cur] = total_out.get(cur, 0) - v
    net = {c: total_in.get(c, 0) - total_out.get(c, 0) for c in closing}
    return {"report": "cashflow", "start": _date_text(period.start), "end": _date_text(period.end),
            "opening": _money_list(opening, True), "inflows": inflows, "outflows": outflows,
            "total_in": _money_list(total_in, True), "total_out": _money_list(total_out, True),
            "net": _money_list(net, True), "closing": _money_list(closing, True)}


# ----------------------------------------------------------------- register
def register(ledger, account, period=None, rollup=False):
    _check_ledger(ledger)
    _check_period(period, optional=True)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be true or false, got %r" % (rollup,))
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account %s" % ("'%s'" % account if isinstance(account, str) else repr(account)))
    prefix = account + ":"
    opening, running, rows = {}, {}, []
    for tx in ledger.transactions():
        if period is not None and tx.date > period.end:
            continue
        for p in tx.postings:
            if not (p.account == account or (rollup and p.account.startswith(prefix))):
                continue
            cur, v = p.amount.currency, p.amount.minor
            opening.setdefault(cur, 0)
            running.setdefault(cur, 0)
            running[cur] += v
            if period is not None and tx.date < period.start:
                opening[cur] += v
                continue
            rows.append({"date": _date_text(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                         "account": p.account, "amount": _m(v, cur), "balance": _m(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": rollup,
            "start": _date_text(period.start) if period is not None else None,
            "end": _date_text(period.end) if period is not None else None,
            "opening": _money_list(opening, True), "rows": rows, "closing": _money_list(running, True)}


# ---------------------------------------------------------------- net worth
def net_worth(ledger, period, step="month"):
    _check_ledger(ledger)
    _check_period(period)
    if not isinstance(step, str) or step not in STEPS:
        raise ReportError("unknown step %r: expected week, month, quarter or year" % (step,))
    steps = periods(period.start, period.end, step)
    txs = ledger.transactions()
    points = []
    for st in steps:
        d = st.end
        assets, liabilities = {}, {}
        for tx in txs:
            if tx.date > d:
                break
            for p in tx.postings:
                t = _type_of(p.account)
                if t in ("asset", "liability"):
                    cur = p.amount.currency
                    assets.setdefault(cur, 0)
                    liabilities.setdefault(cur, 0)
                    if t == "asset":
                        assets[cur] += p.amount.minor
                    else:
                        liabilities[cur] -= p.amount.minor
        net = {c: assets[c] - liabilities[c] for c in assets}
        points.append({"date": _date_text(d), "assets": _money_list(assets, True),
                       "liabilities": _money_list(liabilities, True), "net": _money_list(net, True)})
    return {"report": "net_worth", "start": _date_text(period.start), "end": _date_text(period.end),
            "step": step, "points": points}


# --------------------------------------------------------------- rendering
def _kind(report):
    if not isinstance(report, dict) or report.get("report") not in REPORT_KINDS:
        raise ReportError("not a report: %r" % (report,))
    return report["report"]


def _mt(m):
    return "%s %s" % (m["amount"], m["currency"])


def _blocks(width, *blocks):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def _text_trial_balance(r):
    title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
    rows = [[a["account"], a["type"], _mt(a["debit"]) if a["debit"] else "",
             _mt(a["credit"]) if a["credit"] else ""] for a in r["accounts"]]
    rows += [["Total", "", _mt(t["debit"]), _mt(t["credit"])] for t in r["totals"]]
    return title, ["Account", "Type", "Debit", "Credit"], rows, "llrr"


def _text_balance_sheet(r):
    title = "Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet"
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label, extra=()):
        sec = r[key]
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["balance"])] for a in sec["accounts"]]
        b += list(extra)
        b += [[total_label, _mt(m)] for m in sec["total"]]
        return b

    rows = _blocks(2, block("assets", "Assets", "Total assets"),
                   block("liabilities", "Liabilities", "Total liabilities"),
                   block("equity", "Equity", "Total equity",
                         [["  Retained earnings", _mt(m)] for m in r["equity"]["retained_earnings"]]))
    return title, ["Account", "Balance"], rows, "lr"


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label):
        sec = r[key]
        b = [[heading, "", ""]]
        b += [["  " + a["account"], _mt(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
        b += [[total_label, _mt(m), ""] for m in sec["total"]]
        return b

    rows = _blocks(3, block("income", "Income", "Total income"),
                   block("expenses", "Expenses", "Total expenses"),
                   [["Net income", _mt(m), ""] for m in r["net"]])
    return title, ["Account", "Amount", "Percent"], rows, "lrr"


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])

    def block(lines, totals, heading, total_label):
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["amount"])] for a in lines]
        b += [[total_label, _mt(m)] for m in totals]
        return b

    rows = _blocks(2, [["Opening balance", _mt(m)] for m in r["opening"]],
                   block(r["inflows"], r["total_in"], "Money in", "Total money in"),
                   block(r["outflows"], r["total_out"], "Money out", "Total money out"),
                   [["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]])
    return title, ["Account", "Amount"], rows, "lr"


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for p in r["points"]:
        if not p["assets"]:
            rows.append([p["date"], "", "", ""])
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], _mt(a), _mt(l), _mt(n)])
    return title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr"


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else str(row["id"]), row["payee"], row["account"],
                     _mt(row["amount"]), _mt(row["balance"])])
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr"


_TEXT = {"trial_balance": _text_trial_balance, "balance_sheet": _text_balance_sheet,
         "income_statement": _text_income_statement, "cashflow": _text_cashflow,
         "net_worth": _text_net_worth, "register": _text_register}


def render_text(report):
    kind = _kind(report)
    try:
        title, headers, rows, align = _TEXT[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return title + "\n\n" + render_table(headers, rows, align)


# --------------------------------------------------------------------- CSV
def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        m = a["debit"] or a["credit"]
        rows.append([a["account"], a["type"], m["currency"], a["debit"]["amount"] if a["debit"] else "",
                     a["credit"]["amount"] if a["credit"] else ""])
    return ["account", "type", "currency", "debit", "credit"], rows


def _csv_balance_sheet(r):
    rows = []
    for key in ("assets", "liabilities", "equity"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
    for m in r["equity"]["retained_earnings"]:
        rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
    return ["section", "account", "currency", "balance"], rows


def _csv_income_statement(r):
    rows = []
    for key in ("income", "expenses"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
    return ["section", "account", "currency", "amount", "percent"], rows


def _csv_cashflow(r):
    rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
    rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
    rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
    rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
    return ["section", "account", "currency", "amount"], rows


def _csv_register(r):
    rows = [[row["date"], "" if row["id"] is None else row["id"], row["payee"], row["narration"], row["account"],
             row["amount"]["currency"], row["amount"]["amount"], row["balance"]["amount"]] for row in r["rows"]]
    return ["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows


def _csv_net_worth(r):
    rows = []
    for p in r["points"]:
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return ["date", "currency", "assets", "liabilities", "net"], rows


_CSV = {"trial_balance": _csv_trial_balance, "balance_sheet": _csv_balance_sheet,
        "income_statement": _csv_income_statement, "cashflow": _csv_cashflow,
        "net_worth": _csv_net_worth, "register": _csv_register}


def report_to_csv(report):
    kind = _kind(report)
    try:
        headers, rows = _CSV[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return to_csv(headers, rows)

"""CSV and JSON export, and the plain text table renderer."""

import json

from tallybook.currency import CurrencyError
from tallybook.dates import DateError, parse_date
from tallybook.errors import TallybookError, ValidationError, is_int
from tallybook.money import Money, parse_amount
from tallybook.model import Posting, Transaction

__all__ = ["transactions_to_csv", "transactions_to_json", "transactions_from_json", "render_table", "to_csv",
           "to_json", "money_to_dict", "transaction_to_dict", "ExportError"]


class ExportError(ValidationError):
    """A table or JSON document that cannot be handled."""


# ------------------------------------------------------------------- CSV
def _csv_field(value):
    text = "" if value is None else str(value)
    if any(c in text for c in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "\n".join(lines) + "\n"


def _date_text(d):
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _tags(tx):
    return sorted(set(tx.tags or ()))


CSV_HEADERS = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [tx.id, _date_text(tx.date), tx.flag, tx.payee, tx.narration, ";".join(_tags(tx))]
        if not tx.postings:
            rows.append(head + ["", "", "", ""])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, "", "", p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(CSV_HEADERS, rows)


# ------------------------------------------------------------------ JSON
def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def posting_to_dict(p):
    return {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": _date_text(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _tags(tx),
        "postings": [posting_to_dict(p) for p in tx.postings],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def money_from_dict(obj, where="amount"):
    """Read a money object {"amount": text, "currency": text}; ExportError otherwise."""
    if not isinstance(obj, dict) or set(obj) != {"amount", "currency"}:
        raise ExportError("%s: an amount must be an object with exactly 'amount' and 'currency'" % where)
    if not isinstance(obj["amount"], str) or not isinstance(obj["currency"], str):
        raise ExportError("%s: 'amount' and 'currency' must be text" % where)
    try:
        return Money(parse_amount(obj["amount"], obj["currency"]), obj["currency"])
    except TallybookError as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def transactions_from_json(text):
    try:
        data = json.loads(text)
    except (ValueError, TypeError) as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("expected a JSON array of transactions")
    out = []
    for i, item in enumerate(data, 1):
        where = "transaction %d" % i
        if not isinstance(item, dict):
            raise ExportError("%s: not an object" % where)
        for k in item:
            if k not in _TX_KEYS:
                raise ExportError("%s: unknown key %r" % (where, k))
        for k in ("date", "payee", "postings"):
            if k not in item:
                raise ExportError("%s: missing %r" % (where, k))
        if not isinstance(item["date"], str):
            raise ExportError("%s: invalid date %r" % (where, item["date"]))
        try:
            d = parse_date(item["date"])
        except DateError as e:
            raise ExportError("%s: %s" % (where, e.message)) from None
        tid = item.get("id")
        if tid is not None and (not is_int(tid) or tid < 1):
            raise ExportError("%s: invalid id %r" % (where, tid))
        flag = item.get("flag", "*")
        if flag not in ("*", "!") or not isinstance(flag, str):
            raise ExportError("%s: invalid flag %r" % (where, flag))
        payee = item["payee"]
        if not isinstance(payee, str):
            raise ExportError("%s: payee must be text" % where)
        narration = item.get("narration", "")
        if not isinstance(narration, str):
            raise ExportError("%s: narration must be text" % where)
        tags = item.get("tags", [])
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ExportError("%s: tags must be a list of text" % where)
        postings_raw = item["postings"]
        if not isinstance(postings_raw, list):
            raise ExportError("%s: postings must be a list" % where)
        postings = []
        for j, pr in enumerate(postings_raw, 1):
            pwhere = "%s posting %d" % (where, j)
            if not isinstance(pr, dict):
                raise ExportError("%s: not an object" % pwhere)
            for k in pr:
                if k not in _POSTING_KEYS:
                    raise ExportError("%s: unknown key %r" % (pwhere, k))
            if "account" not in pr or not isinstance(pr["account"], str):
                raise ExportError("%s: account missing or not text" % pwhere)
            amount = pr.get("amount")
            if amount is not None:
                amount = money_from_dict(amount, pwhere)
            note = pr.get("note", "")
            if not isinstance(note, str):
                raise ExportError("%s: note must be text" % pwhere)
            postings.append(Posting(pr["account"], amount, note))
        out.append(Transaction(d, payee, narration, postings, tuple(sorted(set(tags))), flag, tid))
    return out


# ---------------------------------------------------------------- tables
def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_cell(h) for h in headers]
    n = len(headers)
    if n == 0:
        return ""
    if align is None:
        aligns = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("invalid alignment %r" % (align,))
        aligns = list(align)
        if len(aligns) != n or any(a not in ("l", "r") for a in aligns):
            raise ExportError("invalid alignment %r for %d columns" % (align, n))
    body = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells, expected %d" % (len(cells), n))
        body.append(cells)
    widths = [len(h) for h in headers]
    for cells in body:
        for i, c in enumerate(cells):
            widths[i] = max(widths[i], len(c))

    def line(cells):
        parts = [c.ljust(widths[i]) if aligns[i] == "l" else c.rjust(widths[i]) for i, c in enumerate(cells)]
        return "  ".join(parts).rstrip(" ")

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(c) for c in body)
    return "\n".join(out) + "\n"

